'use client'

import { FormEvent, useEffect, useMemo, useState } from 'react'
import { ArrowLeft, ArrowRight, Building2, Check, CheckCircle2, ChevronDown, CirclePlus, ExternalLink, Filter, MapPin, MessageCircle, Pencil, Search, ShieldCheck, Sparkles, StickyNote, Trash2, X, MapPinned, LoaderCircle } from 'lucide-react'

type LeadStatus = 'A contactar' | 'Em negociação' | 'Fechado' | 'Rejeitado'
type WhatsappCheck = 'Não verificado' | 'Confirmado no WhatsApp' | 'Não encontrado no WhatsApp'
type Lead = { id: string; name: string; niche: string; city: string; state: string; country: string; status: LeadStatus; whatsapp: string; notes: string; whatsappCheck?: WhatsappCheck }
const statuses: LeadStatus[] = ['A contactar', 'Em negociação', 'Fechado', 'Rejeitado']
const exampleLeads: Lead[] = [
  { id: 'example-1', name: 'Pizzaria Bella Napoli', niche: 'Pizzaria', city: 'Campinas', state: 'SP', country: 'Brasil', status: 'A contactar', whatsapp: '5519998765432', notes: 'Encontrada no Google Maps. Instagram ativo, mas sem site próprio.' },
  { id: 'example-2', name: 'Auto Center Horizonte', niche: 'Oficina', city: 'Belo Horizonte', state: 'MG', country: 'Brasil', status: 'Em negociação', whatsapp: '5531987654321', notes: 'Proprietário pediu para receber o portfólio na próxima semana.' },
  { id: 'example-3', name: 'Studio Corte & Estilo', niche: 'Salão de Beleza', city: 'Curitiba', state: 'PR', country: 'Brasil', status: 'Fechado', whatsapp: '5541987654321', notes: 'Projeto aprovado. Aguardando envio do briefing inicial.' },
]
const statusStyles: Record<LeadStatus, string> = { 'A contactar': 'bg-amber-50 text-[#9a7b3f] ring-amber-200', 'Em negociação': 'bg-blue-50 text-[#347d79] ring-blue-200', Fechado: 'bg-emerald-50 text-[#347d79] ring-emerald-200', Rejeitado: 'bg-slate-100 text-slate-500 ring-slate-200' }
const normalizePhone = (phone: string) => phone.replace(/\D/g, '')

export default function Page() {
  const [leads, setLeads] = useState<Lead[]>([])
  const [search, setSearch] = useState('')
  const [nicheFilter, setNicheFilter] = useState('Todos')
  const [statusFilter, setStatusFilter] = useState<'Todos' | LeadStatus>('Todos')
  const [isFormOpen, setIsFormOpen] = useState(false)
  const [editingLead, setEditingLead] = useState<Lead | null>(null)
  const [demoLead, setDemoLead] = useState<Lead | null>(null)
  const [isLoaded, setIsLoaded] = useState(false)
  const [mapsNiche, setMapsNiche] = useState('')
  const [mapsCity, setMapsCity] = useState('')
  const [mapsState, setMapsState] = useState('')
  const [mapsLoading, setMapsLoading] = useState(false)
  const [mapsError, setMapsError] = useState('')
  const [mapsMessage, setMapsMessage] = useState('')

  useEffect(() => { const saved = window.localStorage.getItem('prospecmap-leads'); setLeads(saved ? JSON.parse(saved) : exampleLeads); setIsLoaded(true) }, [])
  useEffect(() => { if (isLoaded) window.localStorage.setItem('prospecmap-leads', JSON.stringify(leads)) }, [leads, isLoaded])

  const niches = useMemo(() => [...new Set(leads.map((lead) => lead.niche))].sort(), [leads])
  const filteredLeads = useMemo(() => leads.filter((lead) => `${lead.name} ${lead.city} ${lead.state} ${lead.niche} ${lead.notes}`.toLowerCase().includes(search.toLowerCase()) && (nicheFilter === 'Todos' || lead.niche === nicheFilter) && (statusFilter === 'Todos' || lead.status === statusFilter)), [leads, search, nicheFilter, statusFilter])
  const openNew = () => { setEditingLead(null); setIsFormOpen(true) }
  const openEdit = (lead: Lead) => { setEditingLead(lead); setIsFormOpen(true) }
  const saveLead = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const data = { name: String(form.get('name') || '').trim(), niche: String(form.get('niche') || '').trim(), city: String(form.get('city') || '').trim(), state: String(form.get('state') || '').trim().toUpperCase(), country: String(form.get('country') || 'Brasil').trim(), status: String(form.get('status') || 'A contactar') as LeadStatus, whatsapp: normalizePhone(String(form.get('whatsapp') || '')), notes: String(form.get('notes') || '').trim() }; setLeads((current) => editingLead ? current.map((lead) => lead.id === editingLead.id ? { ...editingLead, ...data } : lead) : [{ id: crypto.randomUUID(), ...data }, ...current]); setIsFormOpen(false) }
  const removeLead = (id: string) => { if (window.confirm('Excluir este lead?')) setLeads((current) => current.filter((lead) => lead.id !== id)) }
  const clearFilters = () => { setSearch(''); setNicheFilter('Todos'); setStatusFilter('Todos') }
  const searchGoogleMaps = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (!mapsNiche.trim() || !mapsCity.trim() || !mapsState.trim()) {
      setMapsError('Preencha o nicho, a cidade e o estado.')
      setMapsMessage('')
      return
    }
    setMapsLoading(true)
    setMapsError('')
    setMapsMessage('')
    try {
      const response = await fetch('/api/hasdata/search', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ niche: mapsNiche.trim(), city: mapsCity.trim(), state: mapsState.trim() }),
      })
      const payload = await response.json()
      if (!response.ok) throw new Error(payload.error || 'Não foi possível pesquisar no Google Maps.')
      const results = Array.isArray(payload.results) ? payload.results : []
      const imported: Lead[] = results.filter((place: { name?: string; phone?: string; website?: string }) => Boolean(place.name?.trim()) && Boolean(place.phone?.trim()) && !place.website?.trim()).map((place: { name: string; phone?: string; address?: string; website?: string; type?: string; rating?: number | string; reviews?: number | string; placeId?: string }) => ({
        id: crypto.randomUUID(),
        name: place.name.trim(),
        niche: place.type || mapsNiche.trim(),
        city: mapsCity.trim(),
        state: mapsState.trim().toUpperCase(),
        country: 'Brasil',
        status: 'A contactar' as LeadStatus,
        whatsapp: normalizePhone(place.phone || ''),
        notes: [
          place.address ? `Endereço: ${place.address}` : '',
          place.website ? `Site: ${place.website}` : '',
          place.rating !== undefined ? `Avaliação Google: ${place.rating}${place.reviews !== undefined ? ` (${place.reviews} avaliações)` : ''}` : '',
          place.placeId ? `Google Maps ID: ${place.placeId}` : '',
        ].filter(Boolean).join(' · '),
      }))
      const existingKeys = new Set(leads.map((lead) => `${lead.name.toLowerCase()}|${lead.city.toLowerCase()}|${lead.state.toLowerCase()}`))
      const uniqueImported = imported.filter((lead, index) => {
        const key = `${lead.name.toLowerCase()}|${lead.city.toLowerCase()}|${lead.state.toLowerCase()}`
        if (existingKeys.has(key)) return false
        existingKeys.add(key)
        return imported.findIndex((item) => `${item.name.toLowerCase()}|${item.city.toLowerCase()}|${item.state.toLowerCase()}` === key) === index
      })
      setLeads((current) => [...uniqueImported, ...current])
      setMapsMessage(uniqueImported.length
        ? `${uniqueImported.length} empresa(s) importada(s) para sua carteira.${imported.length > uniqueImported.length ? ` ${imported.length - uniqueImported.length} duplicada(s) ignorada(s).` : ''}`
        : 'A pesquisa não trouxe empresas novas. Os resultados encontrados já estão na sua carteira.')
    } catch (error) {
      setMapsError(error instanceof Error ? error.message : 'Erro inesperado na pesquisa.')
    } finally {
      setMapsLoading(false)
    }
  }

  if (demoLead) return <DemoPage lead={demoLead} onBack={() => setDemoLead(null)} />
  return <main className="min-h-screen w-full min-w-0 overflow-x-hidden bg-[#f4f6f8] text-slate-950">
    <header className="relative overflow-hidden bg-gradient-to-br from-[#101c2c] via-[#172b42] to-[#23445a] text-white shadow-xl shadow-blue-950/10"><div className="mx-auto max-w-6xl px-4 pb-7 pt-5 sm:px-6 lg:px-8"><div className="flex items-center justify-between gap-4"><div className="flex items-center gap-3"><div className="flex size-10 items-center justify-center rounded-2xl bg-[#c6a96b] text-[#142033]"><Sparkles className="size-5" /></div><div><p className="text-lg font-bold">ProspecMap</p><p className="text-xs text-slate-300">{leads.length} leads na carteira</p></div></div><button onClick={openNew} className="flex shrink-0 items-center gap-2 rounded-xl bg-white px-3 py-2.5 text-sm font-bold text-[#071b3a] shadow-lg hover:bg-cyan-50" type="button"><CirclePlus className="size-4" /><span className="hidden sm:inline">Novo Lead</span><span className="sm:hidden">Novo</span></button></div><div className="mt-7"><p className="text-sm font-medium text-[#d9c28f]">Painel de prospecção</p><h1 className="mt-1 text-2xl font-bold tracking-tight sm:text-3xl">Encontre sua próxima oportunidade.</h1><p className="mt-2 text-sm leading-6 text-slate-300">Organize empresas do Google Maps e gere uma demonstração comercial em segundos.</p></div></div></header>
    <section className="mx-auto max-w-6xl px-4 pt-6 sm:px-6 lg:px-8">
      <div className="mb-5 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <div className="rounded-2xl border border-slate-200/80 bg-white p-4 shadow-sm"><div className="flex items-center justify-between"><span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Total de leads</span><Building2 className="size-4 text-[#347d79]" /></div><p className="mt-3 text-3xl font-black tracking-tight text-slate-900">{leads.length}</p><p className="mt-1 text-xs text-slate-500">Empresas na carteira</p></div>
        <div className="rounded-2xl border border-slate-200/80 bg-white p-4 shadow-sm"><div className="flex items-center justify-between"><span className="text-xs font-semibold uppercase tracking-wide text-slate-500">A contactar</span><MessageCircle className="size-4 text-[#9a7b3f]" /></div><p className="mt-3 text-3xl font-black tracking-tight text-slate-900">{leads.filter((lead) => lead.status === 'A contactar').length}</p><p className="mt-1 text-xs text-slate-500/80">Próximas oportunidades</p></div>
        <div className="rounded-2xl border border-slate-200/80 bg-white p-4 shadow-sm"><div className="flex items-center justify-between"><span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Em negociação</span><Sparkles className="size-4 text-[#347d79]" /></div><p className="mt-3 text-3xl font-black tracking-tight text-slate-900">{leads.filter((lead) => lead.status === 'Em negociação').length}</p><p className="mt-1 text-xs text-slate-500/80">Conversas em andamento</p></div>
        <div className="rounded-2xl border border-slate-200/80 bg-white p-4 shadow-sm"><div className="flex items-center justify-between"><span className="text-xs font-semibold uppercase tracking-wide text-slate-500">WhatsApp conferido</span><Check className="size-4 text-[#347d79]" /></div><p className="mt-3 text-3xl font-black tracking-tight text-slate-900">{leads.filter((lead) => lead.whatsappCheck === 'Confirmado no WhatsApp').length}</p><p className="mt-1 text-xs text-slate-500/80">Confirmados manualmente</p></div>
      </div>
    </section>
    <section className="mx-auto max-w-6xl px-4 pt-6 sm:px-6 lg:px-8">
      <form onSubmit={searchGoogleMaps} className="rounded-3xl border border-white bg-white p-5 shadow-xl shadow-slate-900/[0.06] ring-1 ring-slate-200/70 sm:p-6">
        <div className="flex items-start gap-3">
          <div className="flex size-11 shrink-0 items-center justify-center rounded-xl bg-cyan-50 text-[#347d79]"><MapPinned className="size-5" /></div>
          <div><h2 className="font-bold text-slate-900">Buscar empresas no Google Maps</h2><p className="mt-1 text-sm text-slate-500">Pesquisa real pela HasData. As empresas encontradas serão adicionadas à sua carteira.</p></div>
        </div>
        <div className="mt-4 grid gap-3 sm:grid-cols-3">
          <label className="grid gap-1.5 text-sm font-semibold text-slate-700"><span>Nicho / tipo de empresa</span><input value={mapsNiche} onChange={(e) => setMapsNiche(e.target.value)} placeholder="Ex.: dentistas, pizzarias" className="h-11 min-w-0 rounded-xl border border-slate-200 px-3 font-normal outline-none focus:border-[#347d79]" /></label>
          <label className="grid gap-1.5 text-sm font-semibold text-slate-700"><span>Cidade</span><input value={mapsCity} onChange={(e) => setMapsCity(e.target.value)} placeholder="Ex.: Macaúbas" className="h-11 min-w-0 rounded-xl border border-slate-200 px-3 font-normal outline-none focus:border-[#347d79]" /></label>
          <label className="grid gap-1.5 text-sm font-semibold text-slate-700"><span>Estado</span><input value={mapsState} onChange={(e) => setMapsState(e.target.value)} placeholder="Ex.: BA" maxLength={2} className="h-11 min-w-0 rounded-xl border border-slate-200 px-3 font-normal uppercase outline-none focus:border-[#347d79]" /></label>
        </div>
        <button type="submit" disabled={mapsLoading} className="mt-4 flex h-11 w-full items-center justify-center gap-2 rounded-xl bg-[#172b42] px-4 text-sm font-bold text-white hover:bg-[#23445a] disabled:cursor-not-allowed disabled:opacity-60 sm:w-auto">
          {mapsLoading ? <LoaderCircle className="size-4 animate-spin" /> : <Search className="size-4" />}{mapsLoading ? 'Pesquisando empresas...' : 'Pesquisar e importar empresas'}
        </button>
        {mapsError && <p role="alert" className="mt-3 rounded-xl bg-red-50 p-3 text-sm font-medium text-red-700">{mapsError}</p>}
        {mapsMessage && <p role="status" className="mt-3 rounded-xl bg-emerald-50 p-3 text-sm font-medium text-slate-500">{mapsMessage}</p>}
      </form>
    </section>
    <section className="mx-auto mt-5 max-w-6xl px-4 sm:px-6 lg:px-8"><div className="rounded-3xl border border-slate-200/80 bg-white p-4 shadow-lg shadow-slate-900/[0.04] sm:p-5"><label className="flex h-12 items-center gap-3 rounded-xl border border-slate-200 bg-slate-50 px-3 focus-within:border-[#347d79]"><Search className="size-5 text-slate-400" /><span className="sr-only">Buscar leads</span><input value={search} onChange={(e) => setSearch(e.target.value)} className="min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-slate-400" placeholder="Buscar por empresa, cidade ou nicho..." />{search && <button type="button" onClick={() => setSearch('')} aria-label="Limpar busca"><X className="size-4 text-slate-400" /></button>}</label><div className="mt-3 flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-slate-400"><Filter className="size-3.5" /> Filtros rápidos</div><div className="mt-2 grid grid-cols-2 gap-2 sm:grid-cols-3"><FilterSelect label="Nicho" value={nicheFilter} options={['Todos', ...niches]} onChange={setNicheFilter} /><FilterSelect label="Status" value={statusFilter} options={['Todos', ...statuses]} onChange={setStatusFilter} /><button type="button" onClick={clearFilters} className="h-10 rounded-lg border border-slate-200 text-xs font-semibold text-slate-600 hover:bg-slate-50">Limpar filtros</button></div></div></section>
    <section className="mx-auto w-full min-w-0 max-w-6xl px-3 pb-10 pt-6 sm:px-6 sm:pt-8 lg:px-8"><div className="mb-4"><p className="text-xs font-bold uppercase tracking-[0.16em] text-[#347d79]">Gestão de contatos</p><h2 className="mt-1 text-2xl font-black tracking-tight text-slate-950">{filteredLeads.length} {filteredLeads.length === 1 ? 'lead encontrado' : 'leads encontrados'}</h2></div>{filteredLeads.length === 0 ? <div className="rounded-2xl border border-dashed border-slate-300 bg-white px-5 py-12 text-center"><Building2 className="mx-auto size-9 text-slate-300" /><p className="mt-3 font-semibold text-slate-700">Nenhum lead encontrado</p><p className="mt-1 text-sm text-slate-500">Ajuste os filtros ou adicione uma nova empresa.</p></div> : <div className="grid min-w-0 grid-cols-1 gap-3 sm:gap-4 md:grid-cols-2">{filteredLeads.map((lead) => <LeadCard key={lead.id} lead={lead} onEdit={() => openEdit(lead)} onDelete={() => removeLead(lead.id)} onDemo={() => setDemoLead(lead)} onStatusChange={(status) => setLeads((current) => current.map((item) => item.id === lead.id ? { ...item, status } : item))} onWhatsappCheckChange={(whatsappCheck) => setLeads((current) => current.map((item) => item.id === lead.id ? { ...item, whatsappCheck } : item))} />)}</div>}</section>
    {isFormOpen && <LeadForm lead={editingLead} onClose={() => setIsFormOpen(false)} onSubmit={saveLead} />}
  </main>
}

function FilterSelect({ label, value, options, onChange }: { label: string; value: string; options: string[]; onChange: (value: string) => void }) { return <label className="relative"><span className="sr-only">Filtrar por {label}</span><select value={value} onChange={(e) => onChange(e.target.value)} className="h-10 w-full appearance-none rounded-lg border border-slate-200 bg-white px-2.5 pr-7 text-xs font-semibold text-slate-600 outline-none"><option value={options[0]}>{label}: {options[0]}</option>{options.slice(1).map((option) => <option key={option}>{option}</option>)}</select><ChevronDown className="pointer-events-none absolute right-2 top-3 size-3.5 text-slate-400" /></label> }
function LeadForm({ lead, onClose, onSubmit }: { lead: Lead | null; onClose: () => void; onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { return <div className="fixed inset-0 z-50 flex items-end justify-center bg-[#172b42]/50 p-0 backdrop-blur-sm sm:items-center sm:p-4" onMouseDown={(e) => e.target === e.currentTarget && onClose()}><form onSubmit={onSubmit} className="max-h-[92vh] w-full max-w-lg overflow-y-auto rounded-t-3xl bg-white p-5 shadow-2xl sm:rounded-3xl sm:p-7" aria-label="Formulário de lead"><div className="mb-6 flex items-start justify-between"><div><p className="text-sm font-bold text-[#347d79]">{lead ? 'Editar cadastro' : 'Novo cadastro'}</p><h2 className="mt-1 text-2xl font-bold tracking-tight">{lead ? 'Atualizar lead' : 'Adicionar novo lead'}</h2></div><button type="button" onClick={onClose} aria-label="Fechar formulário" className="rounded-full p-2 text-slate-400 hover:bg-slate-100"><X className="size-5" /></button></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Nome da empresa" name="name" placeholder="Ex: Café Central" defaultValue={lead?.name} required /><Field label="Nicho" name="niche" placeholder="Ex: Pizzaria" defaultValue={lead?.niche} required /><Field label="Cidade" name="city" placeholder="Ex: São Paulo" defaultValue={lead?.city} required /><Field label="Estado" name="state" placeholder="Ex: SP" defaultValue={lead?.state} maxLength={2} required /><Field label="País" name="country" placeholder="Brasil" defaultValue={lead?.country || 'Brasil'} required /><Field label="WhatsApp com DDD" name="whatsapp" placeholder="Ex: (11) 99999-9999" defaultValue={lead?.whatsapp} inputMode="tel" required /><label className="grid gap-1.5 text-sm font-semibold text-slate-700 sm:col-span-2">Status<select name="status" defaultValue={lead?.status || 'A contactar'} className="h-11 rounded-xl border border-slate-200 bg-white px-3 font-normal outline-none"><option>A contactar</option>{statuses.slice(1).map((status) => <option key={status}>{status}</option>)}</select></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700 sm:col-span-2">Notas / observações<textarea name="notes" defaultValue={lead?.notes} placeholder="Anote o que percebeu no Google Maps..." rows={3} className="resize-none rounded-xl border border-slate-200 px-3 py-2.5 font-normal outline-none" /></label></div><button type="submit" className="mt-6 flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-[#172b42] font-bold text-white hover:bg-[#23445a]"><Check className="size-5" />{lead ? 'Salvar alterações' : 'Salvar lead'}</button></form></div> }
function Field({ label, name, placeholder, required, defaultValue, maxLength, inputMode }: { label: string; name: string; placeholder: string; required?: boolean; defaultValue?: string; maxLength?: number; inputMode?: 'tel' }) { return <label className="grid gap-1.5 text-sm font-semibold text-slate-700"><span>{label}</span><input name={name} placeholder={placeholder} defaultValue={defaultValue} required={required} maxLength={maxLength} inputMode={inputMode} className="h-11 rounded-xl border border-slate-200 px-3 font-normal outline-none placeholder:text-slate-400" /></label> }
function LeadCard({ lead, onEdit, onDelete, onDemo, onStatusChange, onWhatsappCheckChange }: { lead: Lead; onEdit: () => void; onDelete: () => void; onDemo: () => void; onStatusChange: (status: LeadStatus) => void; onWhatsappCheckChange: (status: WhatsappCheck) => void }) { const whatsappMessage = `Olá! Vi a ${lead.name} no Google e reparei que vocês ainda não têm site. Posso montar uma prévia de como ficaria e te mandar o link? É sem custo, só para você ver e me dizer o que acha.`; const phone = normalizePhone(lead.whatsapp); const whatsappUrl = `https://wa.me/${phone}?text=${encodeURIComponent(whatsappMessage)}`; const whatsappTestUrl = `https://wa.me/${phone}`; const whatsappCheck = lead.whatsappCheck || 'Não verificado'; const checkStyle = whatsappCheck === 'Confirmado no WhatsApp' ? 'bg-emerald-50 text-[#347d79] ring-emerald-200' : whatsappCheck === 'Não encontrado no WhatsApp' ? 'bg-red-50 text-red-700 ring-red-200' : 'bg-amber-50 text-[#9a7b3f] ring-amber-200'; return <article className="w-full min-w-0 overflow-hidden rounded-2xl border border-slate-200/80 bg-white p-3.5 shadow-sm transition duration-200 hover:border-[#b9d5d1] hover:shadow-lg hover:shadow-slate-900/[0.06] sm:p-5"><div className="flex min-w-0 items-start justify-between gap-2 sm:gap-3"><div className="flex min-w-0 items-start gap-2 sm:gap-3"><div className="flex size-11 shrink-0 items-center justify-center rounded-xl bg-blue-50 text-[#1357a6]"><Building2 className="size-5" /></div><div className="min-w-0"><h3 className="break-words font-bold leading-5 text-slate-900">{lead.name}</h3><p className="mt-0.5 text-sm text-slate-500">{lead.niche}</p></div></div><span className={`max-w-[45%] shrink-0 whitespace-normal rounded-full px-2 py-1 text-center text-[10px] font-bold leading-4 ring-1 sm:px-2.5 sm:text-[11px] ${statusStyles[lead.status]}`}>{lead.status}</span></div><div className="mt-4 flex min-w-0 items-start gap-2 text-sm text-slate-600"><MapPin className="mt-0.5 size-4 shrink-0 text-[#347d79]" /><span className="min-w-0 break-words [overflow-wrap:anywhere]">{lead.city}, {lead.state} · {lead.country}</span></div>{lead.notes && <div className="mt-3 flex gap-2 rounded-xl bg-slate-50 p-3 text-sm leading-5 text-slate-600"><StickyNote className="mt-0.5 size-4 shrink-0 text-slate-400" /><p className="min-w-0 break-words [overflow-wrap:anywhere]">{lead.notes}</p></div>}<div className="mt-4"><span className={`inline-flex max-w-full whitespace-normal break-words rounded-full px-2.5 py-1 text-[11px] font-bold ring-1 ${checkStyle}`}>WhatsApp: {whatsappCheck}</span></div><div className="mt-3 grid min-w-0 grid-cols-1 gap-2 sm:grid-cols-2"><a href={whatsappTestUrl} target="_blank" rel="noreferrer" className="flex h-11 min-w-0 items-center justify-center gap-2 rounded-xl border border-[#16a05d] bg-white px-2 text-xs font-bold text-[#12834c] hover:bg-emerald-50 sm:px-3 sm:text-sm"><Search className="size-4" />Testar número</a><a href={whatsappUrl} target="_blank" rel="noreferrer" className="flex h-11 min-w-0 items-center justify-center gap-2 rounded-xl bg-[#16a05d] px-2 text-xs font-bold text-white hover:bg-[#12834c] sm:px-3 sm:text-sm"><MessageCircle className="size-4" />Abrir mensagem</a><button onClick={onDemo} className="flex h-11 min-w-0 items-center justify-center gap-2 rounded-xl bg-[#172b42] px-2 text-xs font-bold text-white hover:bg-[#23445a] sm:px-3 sm:text-sm" type="button"><Sparkles className="size-4 text-[#d9c28f]" />Ver Site Demo</button></div><p className="mt-3 text-xs leading-5 text-slate-500">Abra “Testar número” e confira no WhatsApp. Depois registre o resultado abaixo; o ProspecMap não verifica automaticamente.</p><div className="mt-2 grid min-w-0 grid-cols-1 gap-2 sm:grid-cols-2"><button type="button" onClick={() => onWhatsappCheckChange('Confirmado no WhatsApp')} className="rounded-xl border border-emerald-200 px-3 py-2 text-xs font-semibold text-[#347d79] hover:bg-emerald-50">Confirmar que tem WhatsApp</button><button type="button" onClick={() => onWhatsappCheckChange('Não encontrado no WhatsApp')} className="rounded-xl border border-red-200 px-3 py-2 text-xs font-semibold text-red-700 hover:bg-red-50">Marcar como não encontrado</button></div><button type="button" onClick={() => onWhatsappCheckChange('Não verificado')} className="mt-2 text-xs font-semibold text-slate-500 underline underline-offset-2">Limpar resultado da verificação</button><div className="mt-3 flex min-w-0 items-center justify-between gap-2"><label className="relative min-w-0 flex-1"><span className="sr-only">Alterar status de {lead.name}</span><select value={lead.status} onChange={(e) => onStatusChange(e.target.value as LeadStatus)} className="h-10 w-full min-w-0 appearance-none rounded-xl border border-slate-200 bg-white px-2 text-xs font-semibold text-slate-600 sm:px-3"><option disabled>Alterar status</option>{statuses.map((status) => <option key={status}>{status}</option>)}</select><ChevronDown className="pointer-events-none absolute right-3 top-3 size-4 text-slate-500" /></label><button type="button" onClick={onEdit} aria-label={`Editar ${lead.name}`} className="rounded-xl border border-slate-200 p-2.5 text-slate-500 hover:bg-slate-50"><Pencil className="size-4" /></button><button type="button" onClick={onDelete} aria-label={`Excluir ${lead.name}`} className="rounded-xl border border-red-100 p-2.5 text-red-500 hover:bg-red-50"><Trash2 className="size-4" /></button></div></article> }

